import { LitElement, html } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { formDescriptionStyles } from './form-layout.styles.js';

/**
 * Help text for a form field, linked via `aria-describedby`.
 *
 * @element bl-form-description
 * @slot - Description text.
 */
@customElement('bl-form-description')
export class BlFormDescription extends LitElement {
  static override styles = [tokens, formDescriptionStyles];

  protected override render() {
    return html`<slot></slot>`;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-form-description': BlFormDescription;
  }
}

import { LitElement, html } from 'lit';
import { customElement } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { formErrorStyles } from './form-layout.styles.js';

/**
 * Error message for a form field. Sets `aria-invalid` on the associated control.
 *
 * @element bl-form-error
 * @slot - Error message text.
 */
@customElement('bl-form-error')
export class BlFormError extends LitElement {
  static override styles = [tokens, formErrorStyles];

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'alert');
  }

  protected override render() {
    return html`
      <div class="error">
        <svg
          class="error-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
          aria-hidden="true"
        >
          <circle cx="12" cy="12" r="10"></circle>
          <line x1="12" y1="8" x2="12" y2="12"></line>
          <line x1="12" y1="16" x2="12.01" y2="16"></line>
        </svg>
        <slot></slot>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-form-error': BlFormError;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { formFieldStyles } from './form-layout.styles.js';

/**
 * Wraps one control + label + description + error.
 * Discovers its slotted control via `@slotchange` and sets
 * `aria-describedby` pointing to description/error IDs.
 *
 * @element bl-form-field
 * @slot - The form control element.
 * @slot label - The label element.
 * @slot description - Help text.
 * @slot error - Error message.
 */
@customElement('bl-form-field')
export class BlFormField extends LitElement {
  static override styles = [tokens, formFieldStyles];

  private _fieldId = `bl-ff-${Math.random().toString(36).slice(2, 9)}`;
  private _descId = `${this._fieldId}-desc`;
  private _errorId = `${this._fieldId}-err`;

  /** Layout direction (inherited from parent bl-form-layout, or set directly). */
  @property({ reflect: true })
  layout: 'vertical' | 'horizontal' = 'vertical';

  /** Whether the field is required. Shows a visual indicator. */
  @property({ type: Boolean })
  required = false;

  override connectedCallback(): void {
    super.connectedCallback();
    // Inherit layout from parent bl-form-layout
    const parent = this.closest('bl-form-layout');
    if (parent) {
      const parentLayout = parent.getAttribute('layout');
      if (parentLayout === 'horizontal') this.layout = 'horizontal';
    }
  }

  private _handleControlSlotChange(e: Event): void {
    const slot = e.target as HTMLSlotElement;
    const nodes = slot.assignedElements({ flatten: true });
    for (const node of nodes) {
      if (node instanceof HTMLElement) {
        this._linkAria(node);
      }
    }
  }

  private _linkAria(control: HTMLElement): void {
    const describedBy: string[] = [];

    // Check if description slot has content
    const descSlot = this.shadowRoot?.querySelector<HTMLSlotElement>('slot[name="description"]');
    if (descSlot && descSlot.assignedElements().length > 0) {
      const descEl = descSlot.assignedElements()[0] as HTMLElement;
      descEl.id = descEl.id || this._descId;
      describedBy.push(descEl.id);
    }

    // Check if error slot has content
    const errSlot = this.shadowRoot?.querySelector<HTMLSlotElement>('slot[name="error"]');
    if (errSlot && errSlot.assignedElements().length > 0) {
      const errEl = errSlot.assignedElements()[0] as HTMLElement;
      errEl.id = errEl.id || this._errorId;
      describedBy.push(errEl.id);
      control.setAttribute('aria-invalid', 'true');
    } else {
      control.removeAttribute('aria-invalid');
    }

    if (describedBy.length > 0) {
      control.setAttribute('aria-describedby', describedBy.join(' '));
    } else {
      control.removeAttribute('aria-describedby');
    }
  }

  private _handleSupportSlotChange = (): void => {
    // Re-link aria when description/error slots change
    const controlSlot = this.shadowRoot?.querySelector<HTMLSlotElement>('slot:not([name])');
    if (controlSlot) {
      const nodes = controlSlot.assignedElements({ flatten: true });
      for (const node of nodes) {
        if (node instanceof HTMLElement) this._linkAria(node);
      }
    }
  };

  protected override render() {
    return html`
      <div class="form-field" part="base">
        <div class="label-area">
          <slot name="label"></slot>
          ${this.required ? html`<span class="required-indicator" aria-hidden="true">*</span>` : ''}
        </div>
        <div class="control-area">
          <slot @slotchange=${this._handleControlSlotChange}></slot>
        </div>
        <div class="support-area">
          <slot name="description" @slotchange=${this._handleSupportSlotChange}></slot>
          <slot name="error" @slotchange=${this._handleSupportSlotChange}></slot>
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-form-field': BlFormField;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { formFieldsetStyles } from './form-layout.styles.js';

/**
 * Groups fields with `<fieldset>` + `<legend>`.
 *
 * @element bl-form-fieldset
 * @slot - `bl-form-field` elements.
 */
@customElement('bl-form-fieldset')
export class BlFormFieldset extends LitElement {
  static override styles = [tokens, formFieldsetStyles];

  /** The legend text for the fieldset. */
  @property()
  legend = '';

  protected override render() {
    return html`
      <fieldset part="base">
        ${this.legend ? html`<legend part="legend">${this.legend}</legend>` : ''}
        <div class="fieldset-content">
          <slot></slot>
        </div>
      </fieldset>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-form-fieldset': BlFormFieldset;
  }
}

import { css } from 'lit';

export const formLayoutStyles = css`
  :host {
    display: block;
  }

  .form-layout {
    display: flex;
    flex-direction: column;
    gap: var(--bl-spacing-lg);
  }

  :host([layout='horizontal']) .form-layout {
    flex-direction: column;
    gap: var(--bl-spacing-lg);
  }

  :host([layout='inline']) .form-layout {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: var(--bl-spacing-md);
  }
`;

export const formFieldStyles = css`
  :host {
    display: block;
  }

  .form-field {
    display: flex;
    flex-direction: column;
    gap: var(--bl-spacing-xs);
  }

  :host([layout='horizontal']) .form-field {
    display: grid;
    grid-template-columns: minmax(120px, auto) 1fr;
    grid-template-rows: auto auto;
    gap: var(--bl-spacing-xs) var(--bl-spacing-md);
    align-items: start;
  }

  :host([layout='horizontal']) .label-area {
    padding-top: var(--bl-spacing-sm);
  }

  :host([layout='horizontal']) .control-area {
    grid-column: 2;
  }

  :host([layout='horizontal']) .support-area {
    grid-column: 2;
  }

  .label-area ::slotted(bl-label) {
    font-weight: 500;
    color: var(--bl-color-neutral-700);
    font-size: var(--bl-font-size-sm);
  }

  .required-indicator {
    color: var(--bl-color-danger-500);
    margin-left: 2px;
  }
`;

export const formDescriptionStyles = css`
  :host {
    display: block;
    color: var(--bl-color-neutral-500);
    font-size: var(--bl-font-size-xs);
    line-height: 1.5;
    font-family: var(--bl-font-family-base);
  }
`;

export const formErrorStyles = css`
  :host {
    display: block;
    color: var(--bl-color-danger-500);
    font-size: var(--bl-font-size-xs);
    line-height: 1.5;
    font-family: var(--bl-font-family-base);
  }

  :host(:empty) {
    display: none;
  }

  .error {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-xs);
  }

  .error-icon {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
  }
`;

export const formFieldsetStyles = css`
  :host {
    display: block;
  }

  fieldset {
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    padding: var(--bl-spacing-lg);
    margin: 0;
  }

  legend {
    font-weight: 600;
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-700);
    padding: 0 var(--bl-spacing-xs);
    font-family: var(--bl-font-family-base);
  }

  .fieldset-content {
    display: flex;
    flex-direction: column;
    gap: var(--bl-spacing-lg);
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { formLayoutStyles } from './form-layout.styles.js';

export type FormLayoutDirection = 'vertical' | 'horizontal' | 'inline';

/**
 * Container that sets the layout direction for form fields.
 *
 * @element bl-form-layout
 * @slot - `bl-form-field` and `bl-form-fieldset` elements.
 */
@customElement('bl-form-layout')
export class BlFormLayout extends LitElement {
  static override styles = [tokens, formLayoutStyles];

  /** Layout direction. */
  @property({ reflect: true })
  layout: FormLayoutDirection = 'vertical';

  protected override render() {
    return html`
      <div class="form-layout" part="base">
        <slot></slot>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-form-layout': BlFormLayout;
  }
}

export { BlFormLayout } from './form-layout.js';
export { BlFormField } from './form-field.js';
export { BlFormDescription } from './form-description.js';
export { BlFormError } from './form-error.js';
export { BlFormFieldset } from './form-fieldset.js';
export type { FormLayoutDirection } from './form-layout.js';
